"""
    This function take a number and a list of
    prime number (supposed to go farter than nb)
    and give the different prime numbers involved in
    the prime decomposition of the number.
    """
def unique_decompo_prime_factors(nb: Any, l_nb_p: Any) -> object {
    decompo = [];
    for elt in l_nb_p {
        if ((nb % elt) == 0) {
            decompo.append(elt);
        }
    }
    return decompo;
}

"""To get the number of weeks and days in given nuber of days"""
def readable_timedelta(days: Any) -> object {
    number_of_weeks = days // 7;
    number_of_days = days % 7;
    return '{} week(s) and {} day(s)'.format(number_of_weeks, number_of_days);
}

